from pathlib import Path
from fractions import Fraction as F
import json,re,random

root=Path(__file__).parent
bank=[[],[],[]]
def q(ch,prompt,options,explanation,source,feedback,check=None):
    assert len(options)==4 and len(set(options))==4 and len(feedback)==3
    # First option is correct before deterministic shuffling.
    if check is not None: assert F(options[0].replace('−','-'))==check
    pairs=list(zip(options,[explanation]+feedback));random.Random(len(bank[ch])+ch*10+44).shuffle(pairs)
    bank[ch].append(dict(prompt=prompt,options=[x[0] for x in pairs],answerIndex=[x[0] for x in pairs].index(options[0]),value=options[0],explanation=explanation,source=source,optionFeedback=[x[1] for x in pairs],expr=''))

q(0,'(−1/2)^4 = ？',['1/16','−1/16','1/8','−2'],'四個負數相乘得正；分子與分母都取四次方：1^4/2^4 = 1/16。','簡報第4頁',['負數的偶數次方是正數。','四次方是連乘四次，不是乘以4或只算三次。','次方不是底數乘以指數。'],F(-1,2)**4)
q(0,'(−5/4)^3 = ？',['−125/64','125/64','−15/12','−125/4'],'奇數個負數相乘得負；5^3=125、4^3=64，所以是 −125/64。','簡報第5頁',['負數的奇數次方應為負。','次方是連乘，不能把分子分母乘以3。','分母4也要取三次方。'],F(-5,4)**3)
q(0,'(−7/9)^2 = ？',['49/81','−49/81','49/9','14/18'],'平方作用於整個括號：負負得正，7^2/9^2=49/81。','評量PDF第16頁',['負數平方為正。','分母也要平方。','平方不是乘以2。'],F(-7,9)**2)
q(0,'(−8/3)^3 = ？',['−512/27','512/27','−24/9','−512/3'],'三個負號的乘積為負；8^3=512、3^3=27。','評量PDF第16頁',['奇數次方仍為負數。','不能把次方當作乘以3。','分母3也要立方。'],F(-8,3)**3)
q(0,'−(2/3)^4 = ？',['−16/81','16/81','−16/3','−8/12'],'先算括號內分數的四次方，外面的負號不在次方範圍內，所以為 −16/81。','評量PDF第16頁概念改編',['外部負號沒有被四次方，不能消失。','分母也要四次方。','四次方表示連乘四次。'],-F(2,3)**4)
q(0,'(−2/5)^4 的值是哪一個？',['16/625','−16/625','16/5','−8/20'],'負數的偶數次方為正，2^4=16、5^4=625。注意與 −(2/5)^4 不同。','簡報第10頁改編',['負號在括號內，四次方後變正。','分母5也要四次方。','不是把分子分母乘以4。'],F(-2,5)**4)
q(0,'(2/3)^2 × 9 = ？',['4','6','36','4/81'],'先算次方得4/9，再乘9得4。','簡報第12頁',['不能以2/3乘以2取代平方。','先計算平方，再處理乘法。','題目是乘以9，不是除以9。'],F(2,3)**2*9)
q(0,'4^2 ÷ (−2/3)^3 = ？',['−54','54','−128/27','−24'],'4^2=16，(−2/3)^3=−8/27；16÷(−8/27)=16×(−27/8)=−54。','簡報第13頁',['正數除以負數，答案為負。','除法要乘除數的倒數。','先計算兩個次方，才能進行除法。'],F(4)**2/F(-2,3)**3)
q(0,'非零數 a 的 0 次方 a^0 等於多少？',['1','0','a','無法判斷'],'a≠0時，a^m÷a^m=1，也等於a^(m−m)=a^0，所以a^0=1。此規則不包含0^0。','簡報第28頁',['0是指數，不表示整個值為0。','a^1才等於a。','題目已限定a不為0，可以判斷。'])
q(0,'【Boss】下列何者與 −(3/4)^6 不同？',['(−3/4)^6','[−(3/4)^2]^3','−(27/64)^2','−729/4096'],'原式是負數 −729/4096；(−3/4)^6 是正729/4096，其他三式皆為負729/4096。','評量PDF第15頁第1題',['這一式負號整體取奇數次方，仍為負，與原式相同。','負號在平方外，值與原式相同。','這就是原式的值。'])

items=[('4^3 × 4^6 = 4^□，□ = ？',9,[18,3,46],'同底數相乘，指數相加：3+6=9。','簡報第17頁','乘法時是指數相加，不是相乘或相減。'),('5^2 × 5^7 = 5^□，□ = ？',9,[14,5,10],'同底數相乘：2+7=9。','簡報第19頁','底數保留，將兩個指數相加。'),('(−3)^4 × (−3) = (−3)^□，□ = ？',5,[4,3,8],'沒有寫指數表示一次方，4+1=5。','簡報第18頁','單獨一個底數的指數是1，不是0或4。'),('11^6 ÷ 11^2 = 11^□，□ = ？',4,[3,8,12],'同底數相除，指數相減：6−2=4。','簡報第21頁','同底數相除應相減，不能相加、相乘或相除。'),('(−6)^5 ÷ (−6)^2 = (−6)^□，□ = ？',3,[7,10,2],'同底數相除：5−2=3。','簡報第22頁','括號內整體才是底數，指數仍相減。'),('(−3/7)^2 × (−3/7)^3 = (−3/7)^□，□ = ？',5,[6,1,4],'分數底數也適用同底數相乘：2+3=5。','簡報第25頁','分數底數也適用指數相加，不能乘指數。'),('(−2/3)^6 ÷ (−2/3)^4 = (−2/3)^□，□ = ？',2,[10,24,1],'同底數相除：6−4=2。','簡報第26頁','先確認底數相同，除法把指數相減。'),('3^2 × 3^□ = 3^5，□ = ？',3,[7,10,2],'由2+□=5，得到□=5−2=3。','評量PDF第16頁','先列2+□=5，要求的是缺少的指數。'),('(−5)^16 ÷ (−5)^4 × (−5)^3 = (−5)^□，□ = ？',15,[9,23,12],'由左至右，同底數相除減指數、相乘加指數：16−4+3=15。','評量PDF第16頁','注意是16−4+3，最後的乘法要加3。'),('【Boss】2^9 + 2^9 + 2^9 + 2^9 = 2^a，a = ？',11,[12,36,9],'四個相同數相加是4×2^9=2^2×2^9=2^11。不能直接把加法套成指數相加。','評量PDF第15頁第8題','先把四項加法提出共同因數，變成4×2^9。')]
for prompt,v,wrong,exp,src,hint in items:q(1,prompt,list(map(str,[v]+wrong)),exp,src,[hint]*3)

q(2,'(2^3)^4 = 2^□，□ = ？',['12','7','81','24'],'次方的次方，指數相乘：3×4=12。','簡報第30頁',['指數相加是同底數相乘的規則，不適用這裡。','不是3的4次方，而是3×4。','只需計算3×4。'])
q(2,'[(−3/7)^2]^3 = (−3/7)^□，□ = ？',['6','5','8','9'],'括號內次方再取次方，指數相乘：2×3=6。','簡報第31頁',['不是同底數兩項相乘，不能加指數。','不是2^3，應為2×3。','外層3不需平方。'])
q(2,'(2×3)^4 = 2^△ × 3^□。△、□依序為？',['4、4','2、2','4、1','1、4'],'乘積的次方可分配到每個因數，兩個指數都為4。','簡報第34頁',['外層指數不是平均分成兩份。','第二個因數3也要四次方。','第一個因數2也要四次方。'])
q(2,'5^5 × 2^5 = ？',['100000','50','1000','1000000'],'相同指數可合併底數：(5×2)^5=10^5=100000。','簡報第39頁',['不是底數乘指數。','指數是5，不是3。','同指數合併底數後仍為5次方。'],F(5)**5*F(2)**5)
q(2,'(4/3)^3 × (3/2)^3 = ？',['8','2','16','64'],'同指數可合併：(4/3×3/2)^3=2^3=8。','簡報第40頁',['合併底數後仍需立方。','2^3是8，不是16。','合併後指數不相加成6。'],F(4,3)**3*F(3,2)**3)
q(2,'3^8 ÷ 3^5 × 2^3 = ？',['216','36','54','729'],'先算3^(8−5)=3^3，再與2^3合併：(3×2)^3=6^3=216。','簡報第41頁',['合併後是6的三次方，不是平方。','合併相同指數時底數相乘。','不能忽略因數2^3。'],F(3)**8/F(3)**5*F(2)**3)
q(2,'5^4 × 2^4 ÷ 10^3 = ？',['10','100','1000','1'],'前兩項合成10^4，再除以10^3，得到10^(4−3)=10。','簡報第44頁',['合併後指數只減3，剩1。','不能忽略除法。','相除的指數差是1，不是0。'],F(5)**4*F(2)**4/F(10)**3)
q(2,'a=(−7/4)^2，b=(−7/4)^3，c=(−7/4)^4，大小關係為？',['c＞a＞b','a＞b＞c','b＞a＞c','a＞c＞b'],'b是負數，a、c是正數。7/4大於1，正的四次方比平方大，因此c＞a＞b。','評量PDF第15頁第6題',['先用奇偶性判斷b為負數，應排最後。','b是負數，不可能最大。','絕對值大於1，四次方大於平方。'])
q(2,'A=(5/6)^60，B=(5/6)^45，C=(5/6)^50，大小關係為？',['A＜C＜B','B＜C＜A','A＜B＜C','C＜A＜B'],'0＜5/6＜1，乘越多次會越小。60＞50＞45，所以A＜C＜B。','評量PDF第16頁計算題',['底數小於1時，指數越大值越小。','50大於45，所以C小於B。','60大於50，所以A小於C。'])
q(2,'【Boss】2×7^26 − (1/8)×(7^27 + 7^26) = ？',['7^26','7^25','0','7^27'],'先提共同因數：7^27+7^26=7^26×(7+1)=8×7^26。乘1/8後為7^26，所以2×7^26−7^26=7^26。','評量PDF第16頁計算題',['這裡是同類項係數相減，不是除法減指數。','2倍減1倍還剩1倍。','減去一倍，不會再乘以7。'])
assert [len(x) for x in bank]==[10,10,10]
for ch,questions in enumerate(bank):
 for item in questions:
  item['hints']=[['先看負號是在括號內，還是在括號外。指數表示連乘的次數。','括號內負底數的偶數次方為正、奇數次方為負；分子分母都要乘方。'],['先辨認是同底數乘法、除法，還是加法。加法不能直接套指數律。','同底數相乘指數相加、相除相減；沒有標示的指數是1。'],['先找括號層次、相同底數或相同指數，決定適用哪一條規則。','次方的次方把指數相乘；乘積的次方可分配給各因數。比較大小時注意底數是否小於1。']][ch]

html=(root/'output/index.html').read_text(encoding='utf8')
html=re.sub(r'const BANK=.*?;\nconst CHAPTERS=',lambda m:'const BANK='+json.dumps(bank,ensure_ascii=False)+';\nconst CHAPTERS=',html,flags=re.S)
chapters=[dict(title='乘方初境',topic='次方與正負',desc='認識分數乘方、奇偶次方與括號，分清負號的作用範圍。',enemy='墨靈 · 乘方守衛'),dict(title='指數秘境',topic='同底數乘除',desc='同底相乘指數加，相除指數減；辨識指數律不能直接套用加法。',enemy='玄靈 · 指數守衛'),dict(title='萬法合一',topic='複合指數律',desc='次方的次方、乘積的次方、大小比較與共同因數，一路破陣。',enemy='燼靈 · 複合守衛')]
html=re.sub(r'const CHAPTERS=.*?;\nconst \$=',lambda m:'const CHAPTERS='+json.dumps(chapters,ensure_ascii=False)+';\nconst $=',html,flags=re.S)
html=html.replace('fraction-wendao-v1','exponent-wendao-v1').replace('分數問道','指數問道').replace('葷素的蟾蜍・修仙試煉','指數律・三境試煉').replace('靈台試煉 · 分數乘除','靈台試煉 · 指數律').replace('以數入道','以冪入道').replace('正負之間，藏天地法則。','乘方之間，藏天地法則。').replace('三重分數封印','三重指數封印')
html=html.replace("function math(text){return String(text)","function math(text){return String(text).replace(/\\^([0-9a-z□△]+)/g,'<sup>$1</sup>')")
html=html.replace("let hint='檢查計算與約分：", "if(q.optionFeedback)return '你選了 '+chosen+'；正確答案是 '+right+'。'+q.optionFeedback[index]+' 正確步驟：'+q.explanation;let hint='檢查計算與約分：")
html=html.replace('四人合陣','指數綜合').replace('可由四人分別驗算、再共同求乘積。分數乘除先看符號，除法乘倒數，連續乘除由左至右。','由同學共同辨識適用的指數律。相同底數相乘指數加、相除指數減；次方的次方指數乘，乘積的次方分別乘方。')
html=html.replace('先記住剛才的正負號與倒數規則','先記住剛才的指數律').replace('關卡章節名稱','關卡章節名稱')
html=re.sub(r'依使用者提供的《107.*?圖像由 AI 原創生成。','依使用者提供的《1上課本CH2-4_指數律》簡報，以及《115國中數學1上實力評量》PDF第15–16頁改編。三章各10題，包含計算、指數填空、正負判別、大小比較及綜合Boss題。每題標示來源頁碼與錯誤選項診斷。圖像沿用分數問道的AI原創水墨修仙素材；兩款遊戲進度各自保存。',html)
(root/'output/exponent.html').write_text(html,encoding='utf8')
(root/'output/exponent-question-bank.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2),encoding='utf8')
print('Built separate exponent game: output/exponent.html; 30 questions with per-option feedback.')
